/**
 * GENERATED FILE — do not edit by hand.
 *
 * Source of truth: the `.sql` files in this directory.
 * Regenerate with: `npm run gen:server-sql`
 *
 * ★ WHY THIS EXISTS.
 *
 * `server/lib/server-sql.ts` used to read these files from disk. A host with no
 * filesystem could not start the server at all, for the
 * sake of one constant. The SQL is inlined here so the server bundles without
 * `node:fs`, and `tests/server/server-sql.test.ts` fails if this copy drifts
 * from the `.sql` files.
 */

/** The inlined statements, keyed by the `.sql` filename they came from. */
export const SERVER_SQL: Readonly<Record<string, string>> = {
  "cast_vote.rpc.sql": "-- server/sql/cast_vote.rpc.sql\n-- Cast or change one vote, atomically (Plan 40 T7).\n--\n-- ★ WHY THIS EXISTS.\n--\n-- `castVote` (`server/lib/vote-service.ts:160-250`) runs five statements inside\n-- one transaction: read the proposal, resolve the voter, read the previous\n-- value, upsert the vote, append an activity row. PostgREST executes one HTTP\n-- request as ONE transaction and offers no begin/commit across requests\n-- (postgrest.org/…/transactions), so there is no way to replay that sequence\n-- over REST without it becoming non-atomic.\n--\n-- The upsert is the reason atomicity matters here. `insert ... on conflict do\n-- update` is safe on its own, but the ACTIVITY ROW it decides to write depends\n-- on the value read two statements earlier. Splitting them across requests\n-- means a vote can be committed while its history row is lost — and the history\n-- is what the decision screen renders as \"who answered\".\n--\n-- ★ IDENTITY COMES FROM `auth.uid()`, NEVER FROM A PARAMETER.\n--\n-- `server/sql/join_event.sql:32-42` documents why at length: a caller-supplied\n-- user id plus `security definer` plus an executable grant is an impersonation\n-- oracle. The same rule applies to every RPC in this directory, without\n-- exception. There is no `p_user_id` argument anywhere below.\n--\n-- ★ `pg_temp` FIRST-PARTY, `public` QUALIFIED.\n--\n-- The body is re-parsed on every call, so an unqualified name could resolve to\n-- a caller-created temp table. `pg_temp` last puts the real schema first.\n-- `extensions` is in the path because Supabase ships pgcrypto there.\n\ncreate or replace function cast_vote(\n  p_event_id     uuid,\n  p_proposal_id  uuid,\n  p_choice       text,\n  p_dealbreaker  boolean default false\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_caller     uuid := auth.uid();\n  v_voter      public.participant;\n  v_previous   text;\n  v_written    public.vote;\n  v_is_change  boolean;\nbegin\n  -- No session, no vote. `auth.uid()` is NULL when the caller's JWT did not\n  -- reach PostgREST (see the callerJwt note in server/lib/supabase-rest.ts).\n  if v_caller is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  -- ★ THE VOTER IS RESOLVED FROM THE CLAIMS, NOT FROM THE REQUEST.\n  --\n  -- A non-participant gets the same answer as a caller who is not the\n  -- event's member: NOT_PARTICIPANT. That is deliberate — distinguishing\n  -- \"you are not in this event\" from \"this event does not exist\" would let a\n  -- stranger probe which event ids are real.\n  select * into v_voter\n  from public.participant\n  where event_id = p_event_id\n    and auth_user_id = v_caller;\n\n  if v_voter.id is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  -- The proposal must belong to this event AND still be open. Checked here as\n  -- well as by RLS because the function runs with the definer's rights, so the\n  -- policy alone is not a gate.\n  if not exists (\n    select 1\n    from public.proposal pr\n    join public.event e on e.id = pr.event_id\n    where pr.id = p_proposal_id\n      and pr.event_id = p_event_id\n      and pr.status = 'OPEN'\n      and e.status in ('DRAFT', 'OPEN', 'VOTING')\n  ) then\n    return jsonb_build_object('error', 'VALIDATION_FAILED');\n  end if;\n\n  select value into v_previous\n  from public.vote\n  where proposal_id = p_proposal_id\n    and participant_id = v_voter.id;\n\n  insert into public.vote (proposal_id, participant_id, value, is_dealbreaker)\n  values (p_proposal_id, v_voter.id, p_choice, p_dealbreaker)\n  on conflict (proposal_id, participant_id)\n  do update set value          = excluded.value,\n                is_dealbreaker = excluded.is_dealbreaker,\n                updated_at     = now()\n  returning * into v_written;\n\n  v_is_change := v_previous is not null and v_previous <> p_choice;\n\n  -- ★ THE LOG RECORDS A CHANGE, NOT A REPEAT.\n  --\n  -- Same rule as the TypeScript path (`server/lib/vote-service.ts:210-215`):\n  -- re-tapping the selected value is invisible in history, but the FIRST vote\n  -- is always logged because \"who has answered\" is the fact that matters.\n  if v_previous is null then\n    insert into public.activity (event_id, actor_id, action, subject_type, subject_id, detail)\n    values (p_event_id, v_voter.id, 'vote_cast', 'proposal', p_proposal_id,\n            jsonb_build_object('to', p_choice));\n  elsif v_is_change then\n    insert into public.activity (event_id, actor_id, action, subject_type, subject_id, detail)\n    values (p_event_id, v_voter.id, 'vote_changed', 'proposal', p_proposal_id,\n            jsonb_build_object('from', v_previous, 'to', p_choice));\n  end if;\n\n  return jsonb_build_object(\n    'error', null,\n    'vote', jsonb_build_object(\n      'proposal_id', v_written.proposal_id,\n      'participant_id', v_written.participant_id,\n      'display_name', v_voter.display_name,\n      'value', v_written.value,\n      'is_dealbreaker', v_written.is_dealbreaker,\n      'created_at', v_written.created_at,\n      'updated_at', v_written.updated_at\n    ),\n    'is_change', (v_previous is not null),\n    'changed_value', v_is_change\n  );\nend;\n$$;\n\n-- ★ EXECUTE IS GRANTED TO `service_role` ONLY.\n--\n-- The same reasoning as `join_event` (`server/sql/join_event.sql:55-64`): the\n-- route is the only caller, and it applies validation the function does not\n-- repeat. Granting `authenticated` would expose a write path that bypasses the\n-- route entirely, with `security definer` rights.\nrevoke all on function cast_vote(uuid, uuid, text, boolean) from public;\ngrant execute on function cast_vote(uuid, uuid, text, boolean) to service_role;\n",
  "confirm_decision.rpc.sql": "-- server/sql/confirm_decision.rpc.sql\n-- Confirm one decision axis, atomically (Plan 40 T7).\n--\n-- ★ WHY THIS EXISTS.\n--\n-- `confirmDecision` (`server/lib/vote-service.ts:571-759`) locks the event row,\n-- checks the organizer, looks for an existing live decision, computes the\n-- outstanding voters, picks the winner, inserts the decision, marks the chosen\n-- proposal CHOSEN, conditionally transitions the event to CONFIRMED and appends\n-- activity. PostgREST cannot replay that as separate requests.\n--\n-- ★ THE LOCK AND THE PARTIAL UNIQUE INDEX ARE BOTH NEEDED.\n--\n-- `for update` on the event row makes two simultaneous confirms wait rather than\n-- both find no live decision and both insert. The partial unique index is the\n-- real guarantee; the lock is what turns a lost race into a wait instead of a\n-- 23505 the organizer would see as a failure. A sequential replay loses the\n-- lock's reach, so the second confirm gets the unique violation the lock exists\n-- to prevent.\n--\n-- ★ THE EVENT IS CONFIRMED ONLY WHEN EVERY AXIS IS DECIDED.\n--\n-- Confirming the time must not declare the place decided. The check is against\n-- `decision`, not against open proposals: setting the chosen proposal to CHOSEN\n-- would otherwise make \"no open proposals\" true immediately and confirm the\n-- event on the first of its two axes.\n--\n-- ★ IDENTITY COMES FROM `auth.uid()`, NEVER FROM A PARAMETER.\n-- See `server/sql/join_event.sql:32-42`.\n\ncreate or replace function confirm_decision(\n  p_event_id      uuid,\n  p_axis          text,\n  p_proposal_id   uuid default null,\n  p_lens          text default 'balanced',\n  p_reason        jsonb default null\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_caller        uuid := auth.uid();\n  v_event         public.event;\n  v_me            public.participant;\n  v_existing      public.decision;\n  v_chosen        uuid;\n  v_decision      public.decision;\n  v_outstanding   text[];\n  v_votes_total   int;\n  v_template      text;\n  v_params        jsonb;\nbegin\n  if v_caller is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  select * into v_event\n  from public.event\n  where id = p_event_id\n  for update;\n\n  if v_event.id is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  select * into v_me\n  from public.participant\n  where event_id = p_event_id\n    and auth_user_id = v_caller;\n\n  if v_me.id is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  if v_me.role <> 'organizer' or v_event.created_by <> v_caller then\n    return jsonb_build_object('error', 'NOT_ORGANIZER');\n  end if;\n\n  -- ★ THE ALREADY-CONFIRMED SHORT CIRCUIT.\n  --\n  -- A second Confirm tap must return the existing decision rather than a\n  -- conflict, so the screen can say \"already confirmed\" with the same numbers.\n  select * into v_existing\n  from public.decision\n  where event_id = p_event_id\n    and axis = p_axis\n    and reopened_at is null\n  limit 1;\n\n  if v_existing.id is not null then\n    select array_agg(p.display_name) into v_outstanding\n    from public.participant p\n    where p.event_id = p_event_id\n      and not exists (\n        select 1 from public.vote v\n        where v.proposal_id = v_existing.proposal_id\n          and v.participant_id = p.id\n      );\n\n    select count(*) into v_votes_total\n    from public.vote v\n    where v.proposal_id = v_existing.proposal_id;\n\n    return jsonb_build_object(\n      'error', null,\n      'already_existed', true,\n      'decision', jsonb_build_object(\n        'id', v_existing.id,\n        'event_id', v_existing.event_id,\n        'axis', v_existing.axis,\n        'proposal_id', v_existing.proposal_id,\n        'lens', v_existing.lens,\n        'reason_template', v_existing.reason_template,\n        'reason_params', v_existing.reason_params,\n        'confirmed_by', v_existing.confirmed_by,\n        'confirmed_at', v_existing.confirmed_at\n      ),\n      'outstanding', coalesce(to_jsonb(v_outstanding), '[]'::jsonb),\n      'votes_total', v_votes_total\n    );\n  end if;\n\n  -- ★ THE ORGANIZER'S CHOICE WINS; ITS ABSENCE MEANS THE LEADER.\n  --\n  -- Without an explicit pick the confirmation must choose the same winner every\n  -- participant sees from the ranking, which is the engine's first place with\n  -- its creation-order tiebreak (AC-2.4.1). The tiebreak is spelled out here\n  -- rather than delegated to the TypeScript engine because this function is the\n  -- only decision-maker on the REST transport.\n  if p_proposal_id is not null then\n    if not exists (\n      select 1 from public.proposal\n      where id = p_proposal_id\n        and event_id = p_event_id\n        and status in ('OPEN', 'REOPENED')\n    ) then\n      return jsonb_build_object('error', 'VALIDATION_FAILED', 'reason', 'NO_PROPOSAL');\n    end if;\n    v_chosen := p_proposal_id;\n  else\n    select pr.id into v_chosen\n    from public.proposal pr\n    where pr.event_id = p_event_id\n      and pr.status in ('OPEN', 'REOPENED')\n    order by\n      (select count(*) from public.vote v where v.proposal_id = pr.id and v.value = 'YES') desc,\n      (select count(*) from public.vote v where v.proposal_id = pr.id and v.value = 'MAYBE') desc,\n      (select count(*) from public.vote v where v.proposal_id = pr.id and v.value = 'NO') asc,\n      pr.created_at asc,\n      pr.id asc\n    limit 1;\n\n    if v_chosen is null then\n      return jsonb_build_object('error', 'VALIDATION_FAILED', 'reason', 'NO_PROPOSAL');\n    end if;\n  end if;\n\n  v_template := coalesce(p_reason->>'templateId', 'decision.confirmed');\n  v_params   := coalesce(p_reason->'params', '{}'::jsonb);\n\n  insert into public.decision (\n    event_id, axis, proposal_id, lens, reason_template, reason_params, confirmed_by\n  ) values (\n    p_event_id, p_axis, v_chosen, coalesce(p_lens, 'balanced'), v_template, v_params, v_me.id\n  )\n  returning * into v_decision;\n\n  update public.proposal\n     set status = 'CHOSEN'\n   where id = v_chosen;\n\n  -- ★ CONFIRMED ONLY WHEN EVERY AXIS WITH A PROPOSAL IS DECIDED.\n  --\n  -- The inner `not exists` is the whole point: an axis whose proposal is still\n  -- open and has no live decision blocks the transition.\n  update public.event e\n     set status = 'CONFIRMED',\n         updated_at = now()\n   where e.id = p_event_id\n     and e.status <> 'CONFIRMED'\n     and not exists (\n       select 1\n       from public.proposal pr\n       where pr.event_id = e.id\n         and pr.status in ('OPEN', 'REOPENED')\n         and not exists (\n           select 1 from public.decision d\n           where d.event_id = e.id\n             and d.proposal_id = pr.id\n             and d.reopened_at is null\n         )\n     );\n\n  select array_agg(p.display_name) into v_outstanding\n  from public.participant p\n  where p.event_id = p_event_id\n    and not exists (\n      select 1 from public.vote v\n      where v.proposal_id = v_chosen\n        and v.participant_id = p.id\n    );\n\n  select count(*) into v_votes_total\n  from public.vote v\n  where v.proposal_id = v_chosen;\n\n  insert into public.activity (event_id, actor_id, action, subject_type, subject_id, detail)\n  values (p_event_id, v_me.id, 'confirmed', 'proposal', v_chosen,\n          jsonb_build_object(\n            'axis', p_axis,\n            'votes_total', v_votes_total,\n            'outstanding', coalesce(to_jsonb(v_outstanding), '[]'::jsonb)\n          ));\n\n  return jsonb_build_object(\n    'error', null,\n    'already_existed', false,\n    'decision', jsonb_build_object(\n      'id', v_decision.id,\n      'event_id', v_decision.event_id,\n      'axis', v_decision.axis,\n      'proposal_id', v_decision.proposal_id,\n      'lens', v_decision.lens,\n      'reason_template', v_decision.reason_template,\n      'reason_params', v_decision.reason_params,\n      'confirmed_by', v_decision.confirmed_by,\n      'confirmed_at', v_decision.confirmed_at\n    ),\n    'outstanding', coalesce(to_jsonb(v_outstanding), '[]'::jsonb),\n    'votes_total', v_votes_total\n  );\nend;\n$$;\n\nrevoke all on function confirm_decision(uuid, text, uuid, text, jsonb) from public;\ngrant execute on function confirm_decision(uuid, text, uuid, text, jsonb) to service_role;\n",
  "create_anonymous_user.rpc.sql": "-- server/sql/create_anonymous_user.rpc.sql\n-- Mint an anonymous identity (Plan 40 T7).\n--\n-- ★ WHY THIS EXISTS.\n--\n-- `createAnonymousUser` (`server/lib/supabase.ts:182-193`) runs\n-- `insert into auth.users (is_anonymous) values (true) returning id`. Two\n-- problems over PostgREST:\n--\n--  1. `auth.users` is not exposed (`db-schemas=public`), so there is no\n--     `/rest/v1/users` to POST to.\n--  2. Even if it were, the WRITE would have to reach a table the client roles\n--     must never touch. `migrations/000_portability.sql:179-200` grants SELECT\n--     and DELETE on it to `service_role` only, and revokes SELECT from `anon`.\n--\n-- So the mint goes through a definer function whose only effect is one row with\n-- `is_anonymous = true`.\n--\n-- ★ `is_anonymous: true` IS LOAD-BEARING.\n--\n-- It is the claim FR-8.36's restrictive policy reads. A row written here without\n-- it would look like an account-holder to the schema, which is why the column is\n-- set explicitly rather than left to its default — the default could change and\n-- this function would silently start minting full accounts.\n--\n-- ★ THIS IS NOT A PUBLIC SIGN-UP ENDPOINT.\n--\n-- Execute is granted to `service_role` only. The route that calls it\n-- (`server/routes/events.ts:50-65`) applies the per-address identity budget\n-- before reaching here; a directly callable mint would be an unthrottled\n-- account-creation endpoint.\n\ncreate or replace function create_anonymous_user()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, auth, extensions, pg_temp\nas $$\ndeclare\n  v_id uuid;\nbegin\n  insert into auth.users (is_anonymous)\n  values (true)\n  returning id into v_id;\n\n  if v_id is null then\n    -- Not reachable while the insert either commits or raises, but a NULL id\n    -- would become `null::uuid` at the caller and read as \"no caller\".\n    raise exception 'create_anonymous_user: insert returned no id';\n  end if;\n\n  return jsonb_build_object('id', v_id, 'is_anonymous', true);\nend;\n$$;\n\nrevoke all on function create_anonymous_user() from public;\ngrant execute on function create_anonymous_user() to service_role;\n",
  "join_event.sql": "-- server/sql/join_event.sql\n-- The atomic guest join (PRD-01 FR-1.16–FR-1.22, §13.3).\n--\n-- ★ ROW-LOCKED, NOT READ-THEN-WRITE.\n--\n-- The participant cap of 10 is a security bound, so a count followed by an\n-- insert is not good enough: two concurrent joins can both read 9 and both\n-- insert, producing an 11th participant. `select ... for update` on the event\n-- row serialises every join for that event and holds the lock for the whole\n-- transaction, so the count cannot change underneath the insert.\n--\n-- ★ THE SAME LOCK MAKES NAME DISAMBIGUATION SAFE.\n--\n-- `Ali (2)` is chosen by reading the names already present. Without the lock,\n-- two people named Ali arriving at once would both see no `Ali (2)` and both\n-- claim it — a unique-violation the user would experience as \"join failed\".\n--\n-- ★ ERRORS ARE TOKENS, NEVER PROSE.\n--\n-- `INVITE_INVALID` and `EVENT_FULL` are the two the route turns into a wire\n-- error. Invalid, expired and revoked all collapse into `INVITE_INVALID`: any\n-- distinction between them is an information leak (FR-1.13).\n--\n-- ★ `pg_temp` IS LISTED EXPLICITLY AND `public` IS QUALIFIED.\n--\n-- The body is re-parsed on every call, so an unqualified name could resolve to\n-- a caller-created temp table. `pg_temp` last puts the real schema first.\n--\n-- `extensions` is in the path because Supabase ships pgcrypto there while this\n-- project installs it into `public`.\n\n-- ★ IDENTITY COMES FROM THE SESSION, NEVER FROM A PARAMETER.\n--\n-- The first draft of this function took the caller's identity as an ARGUMENT\n-- and was executable by `anon`. That is an impersonation oracle: `anon`\n-- execute plus a caller-supplied user id means any caller could join an event\n-- AS ANY USER — including an organizer — and the definer's elevated rights\n-- made that row's creation legitimate.\n--\n-- The identity now comes from `auth.uid()`, which reads the JWT claims the\n-- SERVER set for this request. There is no argument to forge, and the row the\n-- function writes is the caller's own.\n--\n-- ★ WHY IT IS STILL `security definer`.\n--\n-- Because the RLS \"join event\" policy requires the joiner to ALREADY be a\n-- participant (`is_event_participant(event_id)`), a first-time join cannot\n-- insert under its own rights — the policy is what stops a member from\n-- forging an organizer row, and it must not be weakened to let a join in.\n--\n-- The definer's rights are therefore what makes the insert possible, and the\n-- same pattern Phase 2's `redeem_invite` uses: the function is a narrow,\n-- server-only write path, and what it writes is bound to `auth.uid()`.\n--\n-- ★ EXECUTE IS GRANTED TO `service_role` ONLY.\n--\n-- `authenticated` is NOT granted, deliberately. The route rate-limits\n-- redemption per IP and per token (FR-1.15); a direct PostgREST call to this\n-- function would bypass that limiter and turn it into a token-enumeration\n-- oracle. The server is the only caller, and it always goes through the\n-- rate-limited route.\n--\n-- `anon` is not granted either — it has no `auth.uid()`, and a function that\n-- creates a participant row must never be reachable without a session.\n\ncreate or replace function join_event(\n  p_token        text,\n  p_display_name text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_hash          text := encode(digest(p_token, 'sha256'), 'hex');\n  v_caller        uuid := auth.uid();\n  v_anonymous     boolean := coalesce(auth.is_anonymous(), true);\n  v_event         public.event;\n  v_existing      public.participant;\n  v_participant   public.participant;\n  v_count         int;\n  v_base          text;\n  v_candidate     text;\n  v_suffix        text;\n  v_attempt       int;\n  v_result        jsonb;\nbegin\n  -- The lock that closes the cap race and the name race together.\n  select * into v_event\n  from public.event\n  where invite_token_hash = v_hash\n  for update;\n\n  -- Unknown, expired and revoked are indistinguishable here: a rotated or\n  -- revoked token no longer has its hash in the table, so it arrives as\n  -- \"no event\". One return value for all three.\n  if v_event.id is null\n     or v_event.invite_expires_at is null\n     or v_event.invite_expires_at <= now() then\n    return jsonb_build_object('error', 'INVITE_INVALID');\n  end if;\n\n  -- FR-1.20 — the same identity re-joining is routed to the existing row.\n  -- `created: false` lets the client tell a fresh join from a return visit\n  -- without creating a spurious analytics event.\n  select * into v_existing\n  from public.participant\n  where event_id = v_event.id\n    and auth_user_id = v_caller;\n\n  if v_existing.id is not null then\n    return jsonb_build_object(\n      'error', null,\n      'created', false,\n      'participant', jsonb_build_object(\n        'id', v_existing.id,\n        'event_id', v_existing.event_id,\n        'display_name', v_existing.display_name,\n        'role', v_existing.role,\n        'modes', to_jsonb(v_existing.modes),\n        'visibility', v_existing.visibility,\n        'max_travel_minutes', v_existing.max_travel_minutes,\n        'notifications_muted', v_existing.notifications_muted,\n        'has_start_point', exists (\n          select 1 from public.start_point where participant_id = v_existing.id\n        )\n      ),\n      'event', jsonb_build_object(\n        'event_id', v_event.id,\n        'title', v_event.title,\n        'status', v_event.status,\n        'participant_count', (\n          select count(*) from public.participant where event_id = v_event.id\n        )\n      )\n    );\n  end if;\n\n  select count(*) into v_count\n  from public.participant\n  where event_id = v_event.id;\n\n  -- Deliberately distinguishable from INVITE_INVALID: reachable only by a\n  -- holder of a valid link, so naming it leaks nothing and helps the user.\n  if v_count >= 10 then\n    return jsonb_build_object('error', 'EVENT_FULL');\n  end if;\n\n  -- FR-1.19 — a collision never fails the join, it renames.\n  --\n  -- The base is truncated so the suffix still fits the column's 30-character\n  -- bound: `left(base, 30 - len(' (2)'))` for a full-length name. A plain\n  -- `base || ' (2)'` would violate the constraint for a 30-character name and\n  -- turn a supportable case into an error.\n  v_base := left(btrim(p_display_name), 30);\n  v_candidate := v_base;\n  v_attempt := 2;\n\n  while exists (\n    select 1 from public.participant\n    where event_id = v_event.id\n      and display_name = v_candidate\n  ) loop\n    if v_attempt > 999 then\n      -- Pathological density. Still must not fail: a short random tail is\n      -- unique in practice and the user is never blocked from voting.\n      v_candidate := left(v_base, 20) || ' ' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);\n      exit;\n    end if;\n\n    v_suffix := ' (' || v_attempt || ')';\n    v_candidate := left(v_base, greatest(1, 30 - char_length(v_suffix))) || v_suffix;\n    v_attempt := v_attempt + 1;\n  end loop;\n\n  -- The cap trigger is authoritative. It is checked above, under the same\n  -- lock, so this handler exists only so a defensive `EVENT_FULL` from the\n  -- trigger becomes the same jsonb error rather than an aborted transaction.\n  begin\n    insert into public.participant (\n      event_id, auth_user_id, display_name, role, is_anonymous\n    ) values (\n      v_event.id, v_caller, v_candidate, 'member', v_anonymous\n    )\n    returning * into v_participant;\n  exception\n    when check_violation then\n      return jsonb_build_object('error', 'EVENT_FULL');\n  end;\n\n  select count(*) into v_count\n  from public.participant\n  where event_id = v_event.id;\n\n  v_result := jsonb_build_object(\n    'error', null,\n    'created', true,\n    'participant', jsonb_build_object(\n      'id', v_participant.id,\n      'event_id', v_participant.event_id,\n      'display_name', v_participant.display_name,\n      'role', v_participant.role,\n      'modes', to_jsonb(v_participant.modes),\n      'visibility', v_participant.visibility,\n      'max_travel_minutes', v_participant.max_travel_minutes,\n      'notifications_muted', v_participant.notifications_muted,\n      'has_start_point', false\n    ),\n    'event', jsonb_build_object(\n      'event_id', v_event.id,\n      'title', v_event.title,\n      'status', v_event.status,\n      'participant_count', v_count\n    )\n  );\n\n  return v_result;\nend;\n$$;\n\n-- ★ EXECUTE IS GRANTED TO `service_role` ONLY.\n--\n-- `authenticated` is NOT granted, deliberately. The route rate-limits\n-- redemption per IP and per token (FR-1.15); a direct PostgREST call to this\n-- function would bypass that limiter and turn it into a token-enumeration\n-- oracle. The server is the only caller, and it always goes through the\n-- rate-limited route.\n--\n-- `anon` is not granted either — it has no `auth.uid()`, and a function that\n-- creates a participant row must never be reachable without a session.\n--\n-- The function still READS `auth.uid()`, so the server must set the caller's\n-- JWT claims for the duration of the call (see `withCallerTransaction`).\nrevoke all on function join_event(text, text) from public;\ngrant execute on function join_event(text, text) to service_role;\n\n-- ★ THE OLD SIGNATURE IS DROPPED, NOT LEFT BEHIND.\n--\n-- `create or replace` only replaces a function with the SAME argument types.\n-- The four-argument version — which took the caller's identity as a parameter\n-- and was executable by `anon` — therefore SURVIVED the rewrite as a second,\n-- still-callable function. It had to be dropped explicitly.\n--\n-- Leaving it would have been the worst outcome: the impersonation path would\n-- have stayed open, invisible to every test that only called the new\n-- signature.\ndrop function if exists join_event(text, uuid, boolean, text);\n",
  "reopen_event.rpc.sql": "-- server/sql/reopen_event.rpc.sql\n-- Reopen the event's live decisions, atomically (Plan 40 T7).\n--\n-- ★ WHY THIS EXISTS.\n--\n-- `reopenEvent` (`server/lib/reopen-service.ts:84-160`) locks the event row,\n-- checks the caller is the organizer, reads the live decisions, marks them\n-- reopened with the reason, resets the chosen proposals and inserts activity.\n-- PostgREST cannot replay that as separate requests (one request = one\n-- transaction), so it is one RPC.\n--\n-- ★ THE LOCK IS LOAD-BEARING, AND IT IS WHY A SEQUENTIAL REPLAY IS WRONG.\n--\n-- Two organizers tapping reopen at the same moment must not both find a live\n-- decision and both insert activity rows. `for update` on the event row\n-- serialises them, so the second call sees `reopened_at` already set and answers\n-- NO_LIVE_DECISION instead of duplicating the work. Firing the same statements\n-- as separate round trips gives each of them its own transaction, so the lock is\n-- released between the read and the write — reopening exactly the race the lock\n-- was added to close.\n--\n-- ★ IDENTITY COMES FROM `auth.uid()`, NEVER FROM A PARAMETER.\n-- See `server/sql/join_event.sql:32-42`.\n\ncreate or replace function reopen_event(\n  p_event_id  uuid,\n  p_reason    text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions, pg_temp\nas $$\ndeclare\n  v_caller      uuid := auth.uid();\n  v_event       public.event;\n  v_me          public.participant;\n  v_reason      text;\n  v_live_ids    uuid[];\n  v_reopened    int;\nbegin\n  if v_caller is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  -- Normalised the same way `normaliseReason` does it, so an all-whitespace\n  -- reason is EMPTY_REASON rather than a decision row with a blank justification.\n  v_reason := nullif(btrim(coalesce(p_reason, '')), '');\n  if v_reason is null then\n    return jsonb_build_object('error', 'VALIDATION_FAILED');\n  end if;\n\n  -- The lock that serialises two simultaneous reopens.\n  select * into v_event\n  from public.event\n  where id = p_event_id\n  for update;\n\n  if v_event.id is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  select * into v_me\n  from public.participant\n  where event_id = p_event_id\n    and auth_user_id = v_caller;\n\n  if v_me.id is null then\n    return jsonb_build_object('error', 'NOT_PARTICIPANT');\n  end if;\n\n  -- Only the organizer may restart the vote, enforced here as well as in the\n  -- route: a function that trusted only its caller would be one refactor away\n  -- from letting a participant reopen a decision they lost.\n  if v_me.role <> 'organizer' or v_event.created_by <> v_caller then\n    return jsonb_build_object('error', 'NOT_ORGANIZER');\n  end if;\n\n  select array_agg(id) into v_live_ids\n  from public.decision\n  where event_id = p_event_id\n    and reopened_at is null;\n\n  if v_live_ids is null or array_length(v_live_ids, 1) = 0 then\n    return jsonb_build_object('error', 'VALIDATION_FAILED', 'reason', 'NO_LIVE_DECISION');\n  end if;\n\n  -- Both columns in one statement, so a decision can never be marked reopened\n  -- without the reason that justifies it.\n  update public.decision\n     set reopened_at = now(),\n         reopen_reason = v_reason\n   where event_id = p_event_id\n     and reopened_at is null;\n  get diagnostics v_reopened = row_count;\n\n  -- A reopened proposal goes back to REOPENED so it is votable again; CHOSEN\n  -- would leave it unelectable, and OPEN would lose the fact that it was\n  -- decided once and reopened.\n  update public.proposal\n     set status = 'REOPENED'\n   where event_id = p_event_id\n     and status = 'CHOSEN';\n\n  insert into public.activity (event_id, actor_id, action, subject_type, subject_id, detail)\n  values (p_event_id, v_me.id, 'reopened', 'event', p_event_id,\n          jsonb_build_object('reason', v_reason, 'decisions', v_reopened));\n\n  return jsonb_build_object(\n    'error', null,\n    'reopened', v_reopened,\n    'reason', v_reason\n  );\nend;\n$$;\n\nrevoke all on function reopen_event(uuid, text) from public;\ngrant execute on function reopen_event(uuid, text) to service_role;\n",
  "resolve_caller.rpc.sql": "-- server/sql/resolve_caller.rpc.sql\n-- Resolve a user id to the claim the schema reads (Plan 40 T7).\n--\n-- ★ WHY THIS EXISTS.\n--\n-- `resolveCaller` (`server/lib/supabase.ts:270-282`) runs\n-- `select is_anonymous from auth.users where id = $1`. That statement cannot run\n-- over PostgREST, and the reason is a security property this project already\n-- relies on: PostgREST is configured with `db-schemas=public`\n-- (`docker-compose.local.yml:99`), so `auth.users` is NOT exposed. Supabase\n-- configures it the same way, because the table holds every user's id, email\n-- and phone (`migrations/000_portability.sql:179-193`).\n--\n-- So the read goes through a definer function that returns ONE column for ONE id.\n--\n-- ★ IT RETURNS NULL FOR A NON-EXISTENT ID, AND THAT IS THE CONTRACT.\n--\n-- `resolveCaller` maps \"no row\" to `null`, and every caller treats that as \"not\n-- a caller\" — a 403 on a write, an anonymous read. Raising instead would turn a\n-- forged `x-user-id` into a 500 rather than a 403.\n--\n-- ★ `security definer` IS REQUIRED AND IS SAFE HERE.\n--\n-- Required: the server's role must read `auth.users` without that table being\n-- exposed to PostgREST at all.\n--\n-- Safe: the function takes a user id and returns the boolean `is_anonymous` for\n-- it. It writes nothing, and the only fact it discloses is one a caller who\n-- already holds a uuid cannot use — knowing that an id is anonymous says nothing\n-- about who the id belongs to. It is still granted to `service_role` only, so a\n-- browser holding the publishable key cannot use it as a user-id oracle.\n\ncreate or replace function resolve_caller(p_user_id uuid)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, auth, extensions, pg_temp\nas $$\ndeclare\n  v_is_anonymous boolean;\nbegin\n  if p_user_id is null then\n    return null;\n  end if;\n\n  select u.is_anonymous into v_is_anonymous\n  from auth.users u\n  where u.id = p_user_id;\n\n  -- `not found` here means \"no such user\", which the caller models as `null`.\n  if not found then\n    return null;\n  end if;\n\n  return jsonb_build_object('is_anonymous', coalesce(v_is_anonymous, true));\nend;\n$$;\n\nrevoke all on function resolve_caller(uuid) from public;\ngrant execute on function resolve_caller(uuid) to service_role;\n",
};

/**
 * The inlined filenames, in apply order.
 *
 * Mirrors the old `readdirSync(...).sort()` so the apply order is unchanged —
 * `join_event.sql` is the only file today, but a second one must not silently
 * change precedence.
 */
export function serverSqlFiles(): string[] {
  return Object.keys(SERVER_SQL).sort();
}
